import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))
        ans1 = 0
        ans2 = 0
        for i in range(n):
            if a[i] == b[i]:
                ans1 += 1
        for i in range(n):
            for j in range(n):
                if a[i] == b[j]:
                    ans2 += 1
        print(ans1)
        print(ans2)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

